  "vars": {
    "name": {
      "type": "string",
      "description": "Name of the project",
      "prompt": "What is your project's name?"
    },
    "description": {
      "type": "string",
      "description": "Description of the project",
      "prompt": "What is your project's description?"
    },
    "org_name": {
      "type": "string",
      "description": "Organization name",
      "default": "com.example",
      "prompt": "What is your organization name?"
    },
    "network": {
      "type": "boolean",
      "description": "Dio-based HTTP client with auth and logging interceptors",
      "default": true,
      "prompt": "Include the network package?"
    },
    "auth": {
      "type": "boolean",
      "description":
          "Firebase Authentication with email, Google and Apple sign-in",
      "default": true,
      "prompt": "Include authentication?"
    },
    "firestore": {
      "type": "boolean",
      "description": "Cloud Firestore and Cloud Functions wiring",
      "default": false,
      "prompt": "Include Cloud Firestore?"
    },
    "notifications": {
      "type": "boolean",
      "description":
          "Firebase Cloud Messaging, permissions and token registration",
      "default": true,
      "prompt": "Include push notifications?"
    },
    "analytics": {
      "type": "boolean",
      "description": "Event tracking behind a swappable client",
      "default": true,
      "prompt": "Include analytics?"
    },
    "crashlytics": {
      "type": "boolean",
      "description": "Crash and non-fatal error reporting",
      "default": true,
      "prompt": "Include crash reporting?"
    },
    "feature_flags": {
      "type": "boolean",
      "description": "Firebase Remote Config feature flags",
      "default": true,
      "prompt": "Include feature flags?"
    },
    "developer": {
      "type": "boolean",
      "description": "In-app developer tools behind a hidden gesture",
      "default": true,
      "prompt": "Include developer tools?"
    },
    "dashboard": {
      "type": "boolean",
      "description": "Bottom-navigation shell with starter tabs",
      "default": true,
      "prompt": "Include the dashboard shell?"
    }
  }
